{
  "name": "Full Load Optimization",
  "hypothesis": "Previous mandatory deposit rules failed because they forced agents to return with partial loads (1 or 2 items), incurring excessive travel costs relative to food gained. The optimal strategy is to delay the mandatory 'deposit' action until the agent reaches full cargo capacity (cargo=3). By changing the trigger from 'carrying' to a specific condition checking for maximum load, agents will gather three items before returning home, maximizing the amortization of travel energy and ensuring efficient use of the fixed rest interval.",
  "rules": [
    {
      "when": "always",
      "do": "explore"
    },
    {
      "when": "foodNear",
      "do": "gather"
    },
    {
      "when": "tired",
      "do": "rest"
    },
    {
      "when": "cargo==3",
      "do": "deposit"
    }
  ]
}
